fn imag(val: Vec<(f64, f64)>) -> Vec<f64> {
    val.into_iter()
        .map(|(_re, im)| {
            // If the imaginary part is exactly +0.0 or -0.0,
            // normalize it to +0.0. Otherwise return it unchanged.
            if im == 0.0 {
                0.0
            } else {
                im
            }
        })
        .collect()
}

